def _split_at_impl(iterable, pred, keep_separator=False, maxsplit=None):
    it = iter(iterable)
    buf = []
    splits = 0

    for item in it:
        if pred(item):
            if keep_separator:
                buf.append(item)
            yield buf
            buf = []
            splits += 1
            if maxsplit is not None and splits >= maxsplit:
                # Yield remaining items (including current)
                buf.extend([item])
                for remaining_item in it:
                    buf.append(remaining_item)
                yield buf
                return
        else:
            buf.append(item)

    yield buf

